cd /root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d && python3 - <<'EOF'
import json,glob,os
files=glob.glob('subagents/workflows/wf_16f35394-635/agent-*.jsonl')+['subagents/agent-a55a02a9aeaa06fb6.jsonl']
hits=[]
for f in files:
    ids={}
    for l in open(f):
        if 'for s in parser-declarations' in l or 'usage limit' in l.lower() or 'rate_limit' in l or '"isApiErrorMessage":true' in l:
            try: d=json.loads(l)
            except: continue
            ts=d.get('timestamp','')
            m=d.get('message',{})
            if d.get('isApiErrorMessage'):
                print('APIERR',os.path.basename(f),ts,json.dumps(m.get('content'))[:300]); continue
            for c in (m.get('content') or []) if isinstance(m.get('content'),list) else []:
                if c.get('type')=='tool_use' and 'for s in parser-declarations' in json.dumps(c.get('input')):
                    ids[c['id']]=1
                    print('CMD',os.path.basename(f),ts,json.dumps(c['input'])[:900])
                if c.get('type')=='tool_result' and c.get('tool_use_id') in ids:
                    print('RES',ts,json.dumps(c.get('content'))[:1200])
EOF
grep -l 'for s in parser-declarations' *.jsonl 2>/dev/null | head -3

