        for c in cont or []:
            if c.get('type')=='tool_use' and c.get('name')=='Bash' and 'for s in parser-declarations' in c['input'].get('command',''):
                ids[c['id']]=ts
                print('CMD',os.path.basename(f)[6:14],ts,'bg=',c['input'].get('run_in_background'),'|',c['input'].get('description'))
            if c.get('type')=='tool_result' and c.get('tool_use_id') in ids:
                print('  RES',ts,'err=',c.get('is_error'),json.dumps(c.get('content'))[:500])
            if c.get('type')=='text' and 'task-notification' in c.get('text','') and 'failed' in c.get('text',''):
                print('NOTE',ts,c['text'][:600].replace('\n',' '))
EOF

