import re,html
s=open('docs/specification/revival/overview.html',encoding='utf8').read()
a=s.find('The Fortress Programming Environment</h'); a=s.rfind('<h',0,a) if a>0 else 0
i=s.find('id="', s.find('2.4')); 
m=re.search(r'<h[1-6][^>]*>[^<]*(?:<[^>]+>[^<]*)*?Rendering',s[a:])
b=a+m.start() if m else len(s)
sec=s[a:b]; rest=s[b:]
def kinds(x):
    c={}
    for t in re.findall(r'<(pre|figure|div)\b[^>]*class="([^"]*)"',x):
        k=t[0]+'.'+t[1]; c[k]=c.get(k,0)+1
    c['pre(no class)']=len(re.findall(r'<pre>',x))
    return {k:v for k,v in c.items() if any(w in k for w in ('code','pre','fortress','listing','verb','shell','src'))}
